"""Read-only checks for native font arrays, generated maze data and installed dictionaries."""
from pathlib import Path
import subprocess,re,json,tempfile,hashlib,sys,importlib.util,difflib,zlib
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[2];ENGINE=ROOT.parent/'scummvm-fork-splash/engines/igor'
def arrays(t):return {n:[int(x,0) for x in re.findall(r'0x[\da-fA-F]+|\b\d+\b',body)] for n,body in re.findall(r'const (?:uint8|uint32) (\w+::\w+)\[\]\s*=\s*\{(.*?)\};',t,re.S)}
expected=arrays(subprocess.check_output(['python3',str(ROOT/'tools/generate_igor_floppy_font_tables.py')],text=True));current=arrays((ENGINE/'floppy_font.cpp').read_text());font={n:{'values':len(v),'identical':current.get(n)==v} for n,v in expected.items()};assert all(v['identical'] for v in font.values());(OUT/'evidence/fonts.json').write_text(json.dumps(font,indent=2)+'\n');print('Native font tables identical:',len(font))
sys.path.insert(0,str(ROOT/'tools'));sys.argv=['gen_maze_data.py',str(ENGINE)];spec=importlib.util.spec_from_file_location('maze_gen',ROOT/'tools/gen_maze_data.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);rooms,nodes,rows,idsOf,setNames=m.main();generated=m.cpp(rooms,nodes,idsOf);actual=(ENGINE/'parts/part_maze_data.cpp').read_text()
diff=''.join(difflib.unified_diff(generated.splitlines(True),actual.splitlines(True),fromfile='regenerated',tofile='splash-current'));(OUT/'evidence/maze.diff').write_text(diff)
def normalize(s):return re.sub(r'\s+','',re.sub(r'//[^\n]*|/\*.*?\*/','',s,flags=re.S).replace('kMazeBeatenStateIndex','70').replace('partMazeGetRoom','getMazeRoom'))
maze={'rooms':len(rooms),'nodes':len(nodes),'raw_cpp_identical':generated==actual,'equivalent_after_verified_symbol_substitutions':normalize(generated)==normalize(actual)};assert maze['equivalent_after_verified_symbol_substitutions'];(OUT/'evidence/maze.json').write_text(json.dumps(maze,indent=2)+'\n');print(maze)
with tempfile.TemporaryDirectory(prefix='igor-splash-tbl-') as tmp:
 tmp=Path(tmp);c=subprocess.run(['cc',str(ROOT/'reference/scummvm-create-igortbl/create_igortbl.cpp'),'-o',str(tmp/'create_igortbl')],capture_output=True,text=True,check=True);subprocess.run([str(tmp/'create_igortbl')],cwd=tmp,check=True);b=(tmp/'IGOR.TBL').read_bytes();result={'generated_sha256':hashlib.sha256(b).hexdigest(),'compiler_diagnostics':c.stderr,'installed_copies':{str(ROOT/d/'IGOR.TBL'):(ROOT/d/'IGOR.TBL').read_bytes()==b for d in ['.','IGOR','IGOR-CD','igor-en','igor-demo','igor110']}};assert all(result['installed_copies'].values());(OUT/'evidence/tbl-reproduction.json').write_text(json.dumps(result,indent=2)+'\n');print('All six installed dictionaries reproduce')
